return ['domain'=>'page-builder-sandwich','plural-forms'=>'nplurals=2; plural=(n > 1);','language'=>'hi_IN','project-id-version'=>'page-builder-sandwich','pot-creation-date'=>'2026-09-26T16:59:17+00:00','po-revision-date'=>'2026-09-26T16:59:17+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Page Builder Sandwich'=>'Page Builder Sandwich','https://zinndigital.com/wordpress-plugins/page-builder-sandwich'=>'https://zinndigital.com/wordpress-plugins/page-builder-sandwich','The foundation release of the rebuilt Page Builder Sandwich: a settings and About screen, a footprint-free front-end output layer, and one sample content block.'=>'रीबर्ल्ड Page Builder Sandwich का बेस रिलीज़: एक सेटिंग्स और अबाउट स्क्रीन, एक फ़ुटप्रिंट-मुक्त फ्रंट-एंड आउटपुट लेयर, और एक सैंपल कंटेंट ब्लॉक।','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','AI providers'=>'AI प्रदाता','The makers of ChatGPT. A good all-rounder.'=>'ChatGPT के निर्माता। एक अच्छा ऑल-राउंडर।','The makers of Claude. Strong at writing and careful reasoning.'=>'Claude के निर्माता। लेखन और सावधानीपूर्वक तर्क करने में मजबूत।','Google\'s Gemini models. Fast and inexpensive.'=>'Google के Gemini मॉडल। तेज़ और किफायती।','A European AI company with fast, inexpensive models.'=>'तेज़ और किफायती मॉडल वाली एक यूरोपीय एआई कंपनी।','Low-cost models that are good at writing and code.'=>'कम लागत वाले मॉडल जो लेखन और कोडिंग में अच्छे हैं।','One key for models from many different providers.'=>'कई अलग-अलग प्रदाताओं के मॉडलों के लिए एक ही कुंजी।','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'OpenAI के API की तरह काम करने वाली कोई भी सेवा, जिसमें आपके अपने कंप्यूटर या सर्वर पर चलने वाला मॉडल भी शामिल है।','General (used when nothing more specific is set)'=>'सामान्य (जब अधिक विशिष्ट कुछ सेट न हो)','Writing and rewriting'=>'लिखना और फिर से लिखना','Translation'=>'अनुवाद','Code and CSS'=>'कोड और सीएसएस','Sorry, you are not allowed to access this page.'=>'क्षमा करें, आपको इस पृष्ठ पर जाने की अनुमति नहीं है।','These settings are shared by every plugin that uses them: %s.'=>'ये सेटिंग्स उन सभी प्लगइन्स द्वारा साझा की जाती हैं जो इनका उपयोग करते हैं: %s।','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'आपकी कुंजियाँ इस साइट के डेटाबेस में एन्क्रिप्टेड हैं और केवल आपके द्वारा चुने गए प्रदाता को भेजी जाती हैं — हमें कभी नहीं।','Step 1 of 2: choose an AI provider'=>'चरण 1 का 2: एक AI प्रदाता चुनें','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'आप अपनी खुद की कुंजी लाते हैं, इसलिए आप अपने उपयोग के अनुसार सीधे प्रदाता को भुगतान करते हैं। निश्चित नहीं हैं? इनमें से कोई भी ठीक काम करता है; आप बाद में और जोड़ सकते हैं।','Next'=>'अगला','Step 2 of 2: connect %s'=>'चरण 2 का 2: %s कनेक्ट करें','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'अपने OpenAI-compatible सेवा का पता दर्ज करें, जो /v1 पर समाप्त होता है। कुंजी (key) की आवश्यकता केवल तभी होती है जब सेवा इसके लिए कहती है।','Open %s and sign in (or create a free account).'=>'%s खोलें और साइन इन करें (या एक निःशुल्क खाता बनाएँ)।','the %s API keys page'=>'%s API कुंजी पृष्ठ','Create a new key and copy it.'=>'एक नई कुंजी बनाएँ और उसे कॉपी करें।','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'इसे नीचे पेस्ट करें और "सहेजें और परीक्षण करें" (Save and test) दबाएँ। यह काम करता है या नहीं, यह जाँचने के लिए हम एक छोटी सी अनुरोध भेजते हैं।','Most providers need a little credit on the account before a key works: %s.'=>'की काम करने से पहले अधिकांश प्रदाताओं को खाते में थोड़े क्रेडिट की आवश्यकता होती है: %s।','add credit'=>'क्रेडिट जोड़ें','← Choose a different provider'=>'← एक अलग प्रदाता चुनें','Address'=>'पता','Saved key ends in …%s — paste a new one to replace it'=>'सहेजी गई कुंजी …%s पर समाप्त होती है — इसे बदलने के लिए एक नई कुंजी पेस्ट करें','Key (optional)'=>'कुंजी (वैकल्पिक)','API key'=>'API कुंजी','Save and test'=>'सहेजें और परीक्षण करें','Providers'=>'प्रदत्ता','Provider'=>'प्रदाता','Status'=>'स्थिति','Key'=>'कुंजी','Get a key'=>'कुंजी प्राप्त करें','Test'=>'टेस्ट','Remove'=>'हटाएँ','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'एक नए प्लगइन संस्करण द्वारा सहेजा गया: इस प्लगइन को अपडेट करें, या कुंजी को फिर से दर्ज करें।','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'सहेजी गई कुंजी अब नहीं खोली जा सकती (साइट की सुरक्षा कुंजियाँ बदल गई हैं)। इसे फिर से दर्ज करें।','Not connected'=>'कनेक्टेड नहीं है','Connected — last test passed %s'=>'जुड़ा हुआ — अंतिम परीक्षण सफल रहा %s','Last test failed: %s'=>'पिछला परीक्षण विफल रहा: %s','Connected — not tested yet'=>'कनेक्टेड — अभी तक परीक्षण नहीं किया गया','Which model to use'=>'कौन सा मॉडल उपयोग करना है','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ उस कार्य के लिए हमारी अनुशंसा को चिह्नित करता है। सूची में वे सभी मॉडल शामिल हैं जिनका आपका की उपयोग कर सकता है, जिन्हें प्रदाता से सीधे पढ़ा जाता है।','— Recommended for the provider —'=>'— प्रदाता के लिए अनुशंसित —','Save models'=>'मॉडल सहेजें','Refresh the model lists from the providers'=>'प्रदाताओं से मॉडल सूचियाँ रीफ्रेश करें','best quality'=>'सर्वोत्तम गुणवत्ता','lowest cost'=>'सबसे कम लागत','fastest'=>'सबसे तेज़','Add a model yourself'=>'खुद एक मॉडल जोड़ें','A model came out today? Paste its exact name to use it straight away.'=>'आज कोई नया मॉडल आया है? उसका इस्तेमाल तुरंत शुरू करने के लिए उसका सटीक नाम यहाँ पेस्ट करें।','Model name'=>'मॉडल का नाम','Add model'=>'मॉडल जोड़ें','Recommended models list'=>'अनुशंसित मॉडल सूची','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'अनुशंसित मॉडल सूची सत्यापित नहीं की जा सकी, इसलिए कोई अनुशंसा नहीं दिखाई जा रही है। प्लगइन को पुनः स्थापित करें, या नीचे दैनिक अपडेट चालू करें।','The list in use was published on %s. Each plugin update brings a fresh one.'=>'उपयोग में लाई जा रही सूची %s को प्रकाशित की गई थी। प्रत्येक प्लगइन अपडेट एक नई सूची लाता है।','Also check Zinn Digital® once a day for an updated list.'=>'अपडेट की गई सूची के लिए दिन में एक बार Zinn Digital® को भी देखें।','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'केवल एक साधारण डाउनलोड अनुरोध भेजा जाता है: कोई कुंजी नहीं, कोई साइट पता नहीं, आपकी सामग्री के बारे में कुछ भी नहीं। सूची पर हस्ताक्षर किए जाते हैं, और हस्ताक्षर जाँच में विफल रहने वाली सूची को अनदेखा कर दिया जाता है।','Last checked %1$s: %2$s.'=>'अंतिम बार जाँच की गई %1$s: %2$s।','Save, and check now if turned on'=>'सहेजें, और चालू होने पर अभी जाँच करें','a newer list was installed'=>'एक नई सूची स्थापित की गई थी','already up to date'=>'पहले से ही अद्यतित है','the download failed the signature check and was ignored'=>'डाउनलोड हस्ताक्षर जाँच में विफल रहा और उसे छोड़ दिया गया','Zinn Digital® could not be reached; the current list stays in use'=>'Zinn Digital® से संपर्क नहीं हो सका; वर्तमान सूची उपयोग में बनी रहेगी','turned off'=>'बंद कर दिया गया','Open'=>'खोलें','Check their status page'=>'उनका स्टेटस पेज देखें','Open your billing page'=>'अपना बिलिंग पृष्ठ खोलें','Open your API keys page'=>'अपना API कुंजियाँ पृष्ठ खोलें','Open the AI settings'=>'AI सेटिंग्स खोलें','Sorry, you are not allowed to do that.'=>'क्षमा करें, आपको ऐसा करने की अनुमति नहीं है।','Unknown provider.'=>'अज्ञात प्रदाता।','Enter the address of your service, for example http://localhost:11434/v1.'=>'अपने सेवा का पता दर्ज करें, उदाहरण के लिए http://localhost:11434/v1।','That does not look like an API key. Copy it again, without spaces.'=>'वह एपीआई कुंजी जैसी नहीं दिखाई देती है। इसे बिना रिक्त स्थानों के दोबारा कॉपी करें।','Paste your API key first.'=>'सबसे पहले अपनी API कुंजी पेस्ट करें।','Key removed.'=>'कुंजी हटा दी गई है।','Models saved.'=>'मॉडल सहेजे गए।','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'मॉडल का सटीक नाम दर्ज करें, उदाहरण के लिए जैसा कि प्रदाता के दस्तावेज़ीकरण में लिखा गया है।','Added %s. Choose it under "Which model to use".'=>'%s जोड़ा गया। इसे "किस मॉडल का उपयोग करें" के तहत चुनें।','Model removed.'=>'मॉडल हटाया गया।','Daily updates are off. The list that came with the plugin is used.'=>'दैनिक अपडेट बंद हैं। प्लगइन के साथ आई सूची का उपयोग किया जाता है।','Checked: %s.'=>'जाँच की गई: %s।','Model lists refreshed.'=>'मॉडल सूचियाँ ताज़ा की गईं।','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'आपकी AI कुंजी आपके किसी प्लगइन के नए संस्करण द्वारा सहेजी गई थी। इस प्लगइन को अपडेट करें, या AI सेटिंग्स में कुंजी को दोबारा दर्ज करें।','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'आपकी सहेजी गई AI कुंजी अब नहीं खोली जा सकती (साइट की सुरक्षा कुंजियाँ बदल गई हैं)। AI सेटिंग्स में इसे फिर से दर्ज करें।','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'AI अभी सेट अप नहीं है। AI सेटिंग्ज़ में किसी AI प्रोवाइडर के लिए एक की जोड़ें।','No model is chosen for this task. Pick one in the AI settings.'=>'इस कार्य के लिए कोई मॉडल नहीं चुना गया है। AI सेटिंग्स में जाकर एक चुनें।','That AI provider is not supported by this version of the plugin.'=>'प्लग्इन के इस संस्करण द्वारा वह AI प्रदाता समर्थित नहीं है।','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'यह साइट आपकी AI सेवा तक नहीं पहुँच सकी। जाँच करें कि यह चल रही है और इसका पता आपके वेब सर्वर से पहुँचा जा सकता है (आपके अपने कंप्यूटर पर मौजूद सेवा होस्ट की गई साइट से पहुँच योग्य नहीं होती है)।','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'यह साइट %s तक नहीं पहुँच सकी। उनका स्टेटस पेज देखें; यदि वे काम कर रहे हैं, तो आपका होस्ट आउटगोइंग कनेक्शन को ब्लॉक कर रहा हो सकता है, या पता गलत है।','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'%s का कहना है कि आपके खाते में कोई क्रेडिट या कोटा शेष नहीं है। उनके साथ अपने खाते में क्रेडिट जोड़ें या अपनी सीमा बढ़ाएं, फिर दोबारा प्रयास करें।','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'%s ने आपकी कुंजी स्वीकार नहीं की। यह गलत टाइप की गई हो सकती है, रद्द की जा चुकी हो सकती है या इसकी समय सीमा समाप्त हो गई हो सकती है। एक नई कुंजी बनाएँ और इसे यहाँ पेस्ट करें।','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s ने आपकी कुंजी के लिए इस अनुरोध को अस्वीकार कर दिया। हो सकता है कि कुंजी के पास इस मॉडल या सुविधा तक पहुँच न हो, या आपके खाते को सत्यापित करने की आवश्यकता हो।','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'आपकी कुंजी के लिए %2$s से "%1$s" मॉडल उपलब्ध नहीं है। AI सेटिंग्स में दूसरा मॉडल चुनें।','Your %2$s plan does not include the model "%1$s". Choose another model in the AI settings, or upgrade your plan with them.'=>'आपके %2$s प्लान में "%1$s" मॉडल शामिल नहीं है। AI सेटिंग्स में कोई दूसरा मॉडल चुनें या उनके साथ अपना प्लान अपग्रेड करें।','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'%s इस बात को सीमित कर रहा है कि आपकी कुंजी कितनी तेज़ी से अनुरोध भेज सकती है। एक मिनट प्रतीक्षा करें और पुनः प्रयास करें, या उनके साथ अपनी दर सीमा बढ़ाएँ।','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'%s में अभी समस्या आ रही है (उनकी ओर से आउटेज या ओवरलोड)। आपकी सेटिंग में कोई खराबी नहीं है। थोड़ी देर में दोबारा प्रयास करें।','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'AI अनुरोध एक ऐसे कारण से विफल हो गया जिसकी हम पहचान नहीं कर सके। पुनः प्रयास करें; यदि यह समस्या बनी रहती है, तो नीचे दिए गए विवरण के साथ सहायता टीम से संपर्क करें।','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'AI प्रदाता ने ऐसे रूप में उत्तर दिया जिसे यह प्लगइन पढ़ नहीं सका। पुनः प्रयास करें; यदि यह समस्या बनी रहती है, तो दूसरा मॉडल चुनें या सहायता टीम से संपर्क करें।','Custom (OpenAI-compatible)'=>'कस्टम (OpenAI-compatible)','Save a key for this provider first.'=>'पहले इस प्रदाता के लिए एक कुंजी सहेजें।','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'आपकी कुंजी काम करती है, लेकिन प्रदाता इसके लिए किसी टेक्स्ट मॉडल की सूची नहीं देता है। नीचे खुद एक मॉडल जोड़ें।','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'कनेक्टेड। %1$s ने %2$s का उपयोग करके उत्तर दिया। आपकी एआई (AI) सुविधाएं उपयोग के लिए तैयार हैं।','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'आपकी उपयोगकर्ता भूमिका को इस साइट पर AI का उपयोग करने की अनुमति नहीं है। किसी प्रशासक से संपर्क करें।','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'यह साइट अपनी मासिक एआई खर्च सीमा तक पहुंच गई है। कोई एडमिनिस्ट्रेटर इसे एआई सेटिंग्स में बढ़ा सकता है।','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'इस साइट ने एआई (AI) अनुरोधों की अपनी मासिक सीमा पूरी कर ली है। एक एडमिनिस्ट्रेटर इसे एआई (AI) सेटिंग्स में बढ़ा सकता है।','Usage and cost'=>'उपयोग और लागत','The log, limits and role permissions apply to AI used through: %s.'=>'लॉग, सीमाएँ और भूमिका अनुमतियाँ %s के माध्यम से उपयोग किए जाने वाले AI पर लागू होती हैं।','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'लागतें अनुमानित हैं, जिन्हें प्रकाशित मूल्यों के आधार पर तैयार किया गया है; ज्ञात मूल्य न होने वाले मॉडल की कीमत शून्य मानी जाती है।','This month: %1$s requests, about %2$s.'=>'इस महीने: %1$s अनुरोध, लगभग %2$s।','When'=>'जब','Who'=>'कौन','Used for'=>'इसके लिए उपयोग किया जाता है','Model'=>'मॉडल','Tokens in / out'=>'इनपुट / आउटपुट टोकन','About'=>'के बारे में','Result'=>'परिणाम','No AI requests have been made yet.'=>'अभी तक कोई AI अनुरोध नहीं किया गया है।','Done'=>'पूर्ण','Limits and permissions'=>'सीमाएं और अनुमतियां','Monthly spending limit (US dollars)'=>'मासिक खर्च सीमा (US डॉलर)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'कोई सीमा न होने के लिए खाली छोड़ दें। अनुमानित लागत उस तक पहुँचने पर AI महीने के बाकी दिनों के लिए रुक जाता है।','Monthly request limit'=>'मासिक अनुरोध सीमा','Leave empty for no limit.'=>'कोई सीमा न रखने के लिए खाली छोड़ें।','Who may use AI'=>'कौन एआई का उपयोग कर सकता है','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'प्लगइन की सुविधाओं का उपयोग करने वाले सभी लोगों को AI का उपयोग करने की अनुमति देने के लिए किसी पर भी टिक न करें। एडमिनिस्ट्रेटर हमेशा इसका उपयोग कर सकते हैं।','Save limits and permissions'=>'सीमाएँ और अनुमतियाँ सहेजें','Limits and permissions saved.'=>'सीमाएँ और अनुमतियाँ सहेजी गईं।','Security error, please refresh the page and try again.'=>'सुरक्षा त्रुटि, कृपया पेज को रीफ़्रेश करें और पुनः प्रयास करें।','Missing newsletter settings. Please contact the admin.'=>'न्यूज़लेटर सेटिंग्स गायब हैं। कृपया व्यवस्थापक से संपर्क करें।','Invalid newsletter settings. Please contact the admin.'=>'अमान्य न्यूज़लेटर सेटिंग्स। कृपया व्यवस्थापक से संपर्क करें।','Invalid email address.'=>'अमान्य ईमेल पता।','Too many attempts. Please try again in a few minutes.'=>'बहुत सारे प्रयास। कृपया कुछ मिनटों बाद पुनः प्रयास करें।','Something went wrong. Please contact the admin.'=>'कुछ गलत हो गया। कृपया व्यवस्थापक से संपर्क करें।','Map'=>'मैप','Background video'=>'बैकग्राउंड वीडियो','%1$s: %2$d font files stored, stylesheet %3$s'=>'%1$s: %2$d फ़ॉन्ट फ़ाइलें संग्रहीत, स्टाइलशीट %3$s','That family is not stored.'=>'वह फ़ैमिली संग्रहीत नहीं है।','Removed.'=>'हटाया गया।','That is not a valid font family name.'=>'वह एक मान्य फ़ॉन्ट फ़ैमिली नाम नहीं है।','Google Fonts did not return that family. Check the name and try again.'=>'Google Fonts ने वह फ़ैमिली नहीं लौटाई। नाम जाँचें और पुनः प्रयास करें।','The font files could not be downloaded or saved. Check that the uploads folder is writable.'=>'फ़ॉन्ट फ़ाइलें डाउनलोड या सहेजी नहीं जा सकीं। जाँचें कि अपलोड फ़ोल्डर लिखने योग्य है।','The font stylesheet could not be saved. Check that the uploads folder is writable.'=>'फ़ॉन्ट स्टाइलशीट सहेजी नहीं जा सकी। जांचें कि अपलोड फ़ोल्डर में लिखने की अनुमति है या नहीं।','The admin screen\'s scripts are missing from this copy of the plugin. Reinstall it from a released package.'=>'प्लगइन की इस कॉपी से एडमिन स्क्रीन की स्क्रिप्ट्स गायब हैं। इसे किसी रिलीज़ किए गए पैकेज से दोबारा इंस्टॉल करें।','This screen needs JavaScript.'=>'इस स्क्रीन के लिए जावास्क्रिप्ट की आवश्यकता है।','Languages'=>'भाषाएँ','Upgrade'=>'अपग्रेड करें','Pricing'=>'मूल्य निर्धारण','Start Trial'=>'ट्रायल शुरू करें','Account'=>'खाता','Contact Us'=>'संपर्क करें','Affiliation'=>'संबद्धता','the kind of softwarePlugin'=>'प्लगइन','greetingHey %s,'=>'अरे %s,','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info. This will help us make the %s more compatible with your site and better at doing what you need it to.'=>'सुरक्षा और फ़ीचर अपडेट, शैक्षणिक सामग्री, और कभी-कभार मिलने वाले ऑफ़र के लिए ईमेल सूचनाएँ प्राप्त करने के लिए ऑप्ट-इन करें, और कुछ बुनियादी WordPress पर्यावरण जानकारी साझा करें। इससे हमें %s को आपकी साइट के साथ अधिक संगत बनाने और आपकी आवश्यकता के अनुसार काम करने में बेहतर बनाने में मदद मिलेगी।','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info.'=>'सुरक्षा और फ़ीचर अपडेट, शैक्षणिक सामग्री, और कभी-कभार मिलने वाले ऑफ़र के लिए ईमेल सूचनाएँ पाने और कुछ बुनियादी WordPress वातावरण जानकारी साझा करने के लिए ऑप्ट-इन करें।','If you skip this, that\'s okay! %1$s will still work just fine.'=>'यदि आप इसे छोड़ देते हैं, तो कोई बात नहीं! %1$s फिर भी ठीक से काम करता रहेगा।','Allow & Continue'=>'अनुमति दें और जारी रखें','verbSkip'=>'छोड़ें','Skipping, please wait'=>'छोड़ रहा है, कृपया प्रतीक्षा करें','Continue'=>'जारी रखें','Please wait'=>'कृपया प्रतीक्षा करें','as activating pluginActivating'=>'सक्रिय हो रहा है','This will allow %s to'=>'यह %s को अनुमति देगा','Privacy Policy'=>'गोपनीयता नीति','Terms of Service'=>'सेवा की शर्तें','License Agreement'=>'लाइसेंस समझौता','Have a license key?'=>'क्या आपके पास लाइसेंस कुंजी है?','Activate License'=>'लाइसेंस सक्रिय करें','View Basic Profile Info'=>'बेसिक प्रोफ़ाइल जानकारी देखें','Your WordPress user\'s: first & last name, and email address'=>'आपके WordPress उपयोगकर्ता का: पहला और अंतिम नाम, और ईमेल पता','View Basic Website Info'=>'बुनियादी वेबसाइट जानकारी देखें','Homepage URL & title, WP & PHP versions, and site language'=>'होमपेज यूआरएल और शीर्षक, WP और PHP संस्करण, और साइट की भाषा','View Basic %s Info'=>'बुनियादी %s जानकारी देखें','Current %s & SDK versions, and if active or uninstalled'=>'वर्तमान %s और SDK संस्करण, और क्या यह सक्रिय है या अनइंस्टॉल किया गया है','Newsletter'=>'न्यूज़लेटर','Updates, announcements, marketing, no spam'=>'अपडेट, घोषणाएं, विपणन, कोई स्पैम नहीं','View Diagnostic Info'=>'डायग्नोस्टिक जानकारी देखें','WordPress & PHP versions, site language & title'=>'WordPress और PHP संस्करण, साइट की भाषा और शीर्षक','View Plugins & Themes List'=>'प्लगइन और थीम की सूची देखें','Names, slugs, versions, and if active or not'=>'नाम, स्लग, संस्करण, और सक्रिय हैं या नहीं','optional'=>'वैकल्पिक','Never miss an important update'=>'महत्वपूर्ण अपडेट कभी न चूकें','We have introduced this opt-in so you never miss an important update and help us make the %s more compatible with your site and better at doing what you need it to.'=>'हमने यह ऑप्ट-इन पेश किया है ताकि आप कोई भी महत्वपूर्ण अपडेट न चूकें और %s को आपकी साइट के साथ अधिक संगत बनाने तथा आपकी ज़रूरतों को पूरा करने में बेहतर बनाने में हमारी मदद कर सकें।','Thank you for updating to %1$s v%2$s!'=>'%1$s v%2$s पर अपडेट करने के लिए धन्यवाद!','The prefix must be 1 to 8 lowercase letters or digits, start with a letter, and must not name the plugin.'=>'उपसर्ग 1 से 8 छोटे अक्षरों या अंकों का होना चाहिए, एक अक्षर से शुरू होना चाहिए, और प्लगइन का नाम नहीं होना चाहिए।','You are not allowed to edit this item.'=>'आपको इस आइटम को संपादित करने की अनुमति नहीं है।','You are not allowed to do this.'=>'आपको ऐसा करने की अनुमति नहीं है।','Safe mode was turned off because it no longer matches your login. Reload the page.'=>'सेफ़ मोड बंद कर दिया गया क्योंकि यह अब आपके लॉगिन से मेल नहीं खाता है। पेज को रीलोड करें।','Only an administrator can use safe mode.'=>'केवल एक प्रशासक ही सेफ़ मोड का उपयोग कर सकता है।','Safe mode needs a normal browser login.'=>'सेफ़ मोड के लिए सामान्य ब्राउज़र लॉगिन की आवश्यकता होती है।','Safe mode could not be set up.'=>'सेफ़ मोड सेट अप नहीं किया जा सका।','Safe mode needs write access to the wp-content/mu-plugins folder.'=>'सेफ़ मोड को wp-content/mu-plugins फ़ोल्डर में लिखने की अनुमति की आवश्यकता है।','Safe mode could not write to the wp-content/mu-plugins folder.'=>'सेफ़ मोड wp-content/mu-plugins फ़ोल्डर में लिख नहीं सका।','Sandwich Studio'=>'सैंडविच स्टूडियो','That page does not exist, or it has been deleted.'=>'वह पृष्ठ मौजूद नहीं है, या उसे हटा दिया गया है।','Sorry, you are not allowed to edit this item in Sandwich Studio.'=>'क्षमा करें, आपको Sandwich Studio में इस आइटम को संपादित करने की अनुमति नहीं है।','Sandwich Studio is not built. Reinstall the plugin.'=>'सैंडविच स्टूडियो नहीं बना है। प्लगइन को पुनः इंस्टॉल करें।','Add title'=>'शीर्षक जोड़ें','Type / to choose a block'=>'ब्लॉक चुनने के लिए / टाइप करें','Loading Sandwich Studio…'=>'सैंडविच स्टूडियो लोड हो रहा है…','Sandwich Studio needs JavaScript. Use the normal editor instead.'=>'सैंडविच स्टूडियो के लिए जावास्क्रिप्ट आवश्यक है। इसके बजाय सामान्य संपादक का उपयोग करें।','Edit “%s” with Sandwich Studio'=>'Sandwich Studio के साथ "%s" संपादित करें','Edit with Sandwich Studio'=>'सैंडविच स्टूडियो के साथ संपादित करें','Blank canvas'=>'रिक्त कैनवास','A migration step is running right now. Try again in a minute.'=>'एक माइग्रेशन स्टेप अभी चल रहा है। एक मिनट बाद पुनः प्रयास करें।','Thank you for subscribing!'=>'सदस्यता लेने के लिए धन्यवाद!','Something went wrong. Please contact the administrator.'=>'कुछ गलत हो गया। कृपया व्यवस्थापक से संपर्क करें।','Years'=>'वर्ष','Months'=>'महीने','Weeks'=>'सप्ताह','Days'=>'दिन','Hours'=>'घंटे','Minutes'=>'मिनट','Seconds'=>'सेकंड','Go to slide %d'=>'स्लाइड %d पर जाएं','You\'re already subscribed to our newsletter'=>'आप पहले से ही हमारे न्यूज़लेटर के सदस्य हैं','Email address is already subscribed.'=>'ईमेल पता पहले से ही सब्सक्राइब है।','MailPoet plugin not found. Please contact the admin.'=>'मेलपोट प्लगइन नहीं मिला। कृपया एडमिन से संपर्क करें।','Built by Neil Lock, CEO of Zinn Digital® Ltd'=>'Zinn Digital® Ltd के सीईओ Neil Lock द्वारा निर्मित','Version %s'=>'संस्करण %s','Page Builder Sandwich website'=>'Page Builder Sandwich वेबसाइट','Zinn Digital® website'=>'Zinn Digital® वेबसाइट','Settings saved.'=>'सेटिंग्स सहेजी गईं।','See the Pro plans and pricing'=>'प्रो योजनाएं और मूल्य निर्धारण देखें','Front-end output'=>'फ्रंट-एंड आउटपुट','Class name prefix'=>'क्लास नाम उपसर्ग','Every class name the plugin prints on your pages starts with this prefix, so the pages do not reveal which plugin built them. 1 to 8 lowercase letters or digits, starting with a letter.'=>'प्लगइन आपके पृष्ठों पर जो भी क्लास नाम प्रिंट करता है, वह इस उपसर्ग से शुरू होता है, ताकि पृष्ठों से यह पता न चले कि उन्हें किस प्लगइन ने बनाया है। 1 से 8 छोटे अक्षर या अंक, जो किसी अक्षर से शुरू होते हैं।','Save'=>'सहेजें','Beta updates'=>'बीटा अपडेट','This site receives beta versions as updates.'=>'यह साइट अपडेट के रूप में बीटा संस्करण प्राप्त करती है।','This site receives stable versions only.'=>'यह साइट केवल स्थिर संस्करण प्राप्त करती है।','Change this on the Account page'=>'इसे खाता पृष्ठ पर बदलें','Beta versions are offered to licensed Pro installations that are connected to their account. Once connected, you can join from the Account page.'=>'बीटा वर्ज़न उन लाइसेंस प्राप्त प्रो इंस्टॉलेशन के लिए उपलब्ध हैं जो उनके खाते से जुड़े हुए हैं। एक बार जुड़ जाने के बाद, आप खाता पृष्ठ से शामिल हो सकते हैं।','The request converting this post stopped before it finished, so the post was skipped. Open it to convert it, or convert it again from here.'=>'इस पोस्ट को बदलने का अनुरोध पूरा होने से पहले ही रुक गया था, इसलिए पोस्ट को छोड़ दिया गया। इसे बदलने के लिए खोलें, या यहीं से इसे दोबारा बदलें।','There is no backup of this post to restore.'=>'पुनर्स्थापित करने के लिए इस पोस्ट का कोई बैकअप मौजूद नहीं है।','The converted content could not be saved.'=>'रूपांतरित सामग्री सहेजी नहीं जा सकी।','Unknown error.'=>'अज्ञात त्रुटि।','No legacy content has been checked yet.'=>'अभी तक किसी भी लेगेसी सामग्री की जाँच नहीं की गई है।','Restoring legacy content: %1$d of %2$d posts.'=>'पुराने कंटेंट को रीस्टोर किया जा रहा है: %1$d / %2$d पोस्ट्स।','Converting legacy content: %1$d of %2$d posts.'=>'लेगेसी सामग्री परिवर्तित की जा रही है: %1$d में से %2$d पोस्ट।','Undo finished: %1$d restored, %2$d failed.'=>'पूर्ववत क्रिया समाप्त: %1$d बहाल किए गए, %2$d विफल रहे।','Conversion finished: %1$d converted, %2$d unchanged, %3$d failed.'=>'रूपांतरण समाप्त: %1$d रूपांतरित, %2$d अपरिवर्तित, %3$d विफल।','Legacy content'=>'लेगेसी सामग्री','Pages made with earlier versions of Page Builder Sandwich are converted to blocks in the background. Every post is backed up first, so each conversion can be undone.'=>'Page Builder Sandwich के पुराने संस्करणों से बनाए गए पृष्ठों को पृष्ठभूमि में ब्लॉक में बदल दिया जाता है। प्रत्येक पोस्ट का पहले बैकअप लिया जाता है, ताकि प्रत्येक रूपांतरण को पूर्ववत् किया जा सके।','%d post still holds legacy content.'=>'%d पोस्ट में अभी भी पुरानी सामग्री है।' . "\0" . '%d पोस्टों में अभी भी पुराना कंटेंट है।','%d post has a backup.'=>'%d पोस्ट का एक बैकअप है।' . "\0" . '%d पोस्ट के लिए बैकअप मौजूद है।','%d post could not be handled'=>'%d पोस्ट को प्रबंधित नहीं किया जा सका' . "\0" . '%d पोस्ट को प्रबंधित नहीं किया जा सका','Post %d'=>'पोस्ट %d','Conversion started. It continues in the background; you can leave this page.'=>'रूपांतरण शुरू हो गया है। यह पृष्ठभूमि में जारी रहेगा; आप इस पृष्ठ को छोड़ सकते हैं।','Convert legacy content'=>'पुराने कंटेंट को कनवर्ट करें','Restore every converted post to its legacy content? Changes made to those posts since they were converted will be lost.'=>'क्या आप परिवर्तित किए गए प्रत्येक पोस्ट को उसकी पुरानी सामग्री में पुनर्स्थापित करना चाहते हैं? उन पोस्ट में रूपांतरण के बाद किए गए परिवर्तन समाप्त हो जाएंगे।','Undo started. It continues in the background; you can leave this page.'=>'पूर्ववत् करने की प्रक्रिया शुरू हो गई है। यह बैकग्राउंड में जारी रहेगी; आप इस पेज को छोड़ सकते हैं।','Undo all conversions'=>'सभी रूपांतरण पूर्ववत करें','Shortcode tag'=>'शॉर्टकोड टैग','Use letters, numbers, dashes and underscores only.'=>'केवल अक्षरों, अंकों, डैश और अंडरस्कोर का उपयोग करें।','Attribute name'=>'विशेषता का नाम','Add attribute'=>'विशेषता जोड़ें','Content'=>'सामग्री','Shortcode'=>'शॉर्टकोड','Choose a shortcode tag in the block settings.'=>'ब्लॉक सेटिंग्स में एक शॉर्टकोड टैग चुनें।','The "%s" control from the old editor is not available in the block editor. Enter the value as text.'=>'पुराने एडिटर का "%s" कंट्रोल ब्लॉक एडिटर में उपलब्ध नहीं है। मान को टेक्स्ट के रूप में दर्ज करें।','Choose image'=>'छवि चुनें','Choose file'=>'फ़ाइल चुनें','— Default —'=>'— डिफ़ॉल्ट —','Advanced styling'=>'उन्नत स्टाइलिंग','Inline CSS'=>'इनलाइन सीएसएस','CSS declarations, for example: min-height: 380px; background-color: #333'=>'CSS घोषणाएँ, उदाहरण के लिए: min-height: 380px; background-color: #333','Effects (legacy classes)'=>'प्रभाव (लिगेसी कक्षाएं)','Space-separated effect names carried over from older versions, for example: hover-shadow'=>'पुराने संस्करणों से लिए गए स्पेस-द्वारा-अलग किए गए प्रभाव नाम, उदाहरण के लिए: hover-shadow','Row'=>'पंक्ति','Width'=>'चौड़ाई','Content width'=>'सामग्री की चौड़ाई','Full width'=>'पूर्ण चौड़ाई','Full width, content kept in the middle'=>'पूर्ण चौड़ाई, सामग्री बीच में रखी गई है','Link'=>'लिंक','Link address'=>'लिंक का पता','Open in a new tab'=>'एक नए टैब में खोलें','Link relationship'=>'लिंक संबंध','Alignment'=>'संरेखण','None'=>'कोई नहीं','Left'=>'बायाँ','Centre'=>'केंद्र','Right'=>'दायाँ','Button text'=>'बटन पाठ','Add text…'=>'पाठ जोड़ें...','Icon'=>'आइकन','SVG markup'=>'SVG मार्कअप','Scripts, links and external references are removed before the icon is shown.'=>'आइकन दिखाने से पहले स्क्रिप्ट, लिंक और बाहरी संदर्भ हटा दिए जाते हैं।','Accessible label'=>'सुगम्य लेबल','Leave empty for a decorative icon.'=>'सजावटी आइकन के लिए खाली छोड़ें।','Paste SVG markup in the block settings.'=>'ब्लॉक सेटिंग्स में SVG मार्कअप पेस्ट करें।','New setting name'=>'नया सेटिंग नाम','For example: title or text'=>'उदाहरण के लिए: शीर्षक या पाठ','Add setting'=>'सेटिंग जोड़ें','Widget'=>'विजेट','Choose a widget'=>'एक विजेट चुनें','Widget area'=>'विजेट क्षेत्र','Choose a widget area'=>'एक विजेट क्षेत्र चुनें','This image has no width and height, so the page will jump when it loads. Choose it from the Media Library, or set its width and height.'=>'इस इमेज की चौड़ाई और ऊँचाई नहीं है, इसलिए लोड होने पर पेज हिलेगा। इसे मीडिया लाइब्रेरी से चुनें, या इसकी चौड़ाई और ऊँचाई सेट करें।','This video is not from the Media Library, so its size is unknown and the page will jump when it loads. Upload it to the Media Library instead.'=>'यह वीडियो मीडिया लाइब्रेरी से नहीं है, इसलिए इसका आकार ज्ञात नहीं है और लोड होने पर पेज उछलेगा। इसके बजाय इसे मीडिया लाइब्रेरी में अपलोड करें।','An image, video or frame in this HTML has no width and height, so the page will jump when it loads. Add width and height attributes to it.'=>'इस HTML में किसी छवि, वीडियो या फ़्रेम की चौड़ाई और ऊँचाई नहीं है, इसलिए लोड होने पर पेज उछलेगा। इसमें चौड़ाई और ऊँचाई के एट्रिब्यूट जोड़ें।','This embed resizes itself after it loads, which moves the content below it. Give it room or place it lower on the page.'=>'यह एम्बेड लोड होने के बाद खुद का आकार बदलता है, जिससे इसके नीचे की सामग्री खिसक जाती है। इसे जगह दें या पेज पर थोड़ा नीचे रखें।','Layout shift'=>'लेआउट शिफ्ट','Heading'=>'शीर्षक','Text'=>'पाठ','Style'=>'शैली','Plain'=>'सादा','Accent'=>'एसेंट','No languages to switch between. The switcher appears when a translation plugin lists two or more languages.'=>'बदलने के लिए कोई भाषाएँ नहीं हैं। जब कोई अनुवाद प्लगइन दो या दो से अधिक भाषाएँ सूचीबद्ध करता है, तब स्विचर दिखाई देता है।','Switcher'=>'स्विचर','Show the current language'=>'वर्तमान भाषा दिखाएँ','%s is also editing this page. Saving may overwrite their changes.'=>'%s भी इस पृष्ठ को संपादित कर रहा है। सहेजने से उनके परिवर्तन अधिलेखित हो सकते हैं।','Block library'=>'ब्लॉक लाइब्रेरी','Layers'=>'परतें','Close panel'=>'पैनल बंद करें','Page canvas'=>'पेज कैनवास','Revisions'=>'संशोधन','Block settings'=>'ब्लॉक सेटिंग्स','Add block: %s'=>'ब्लॉक जोड़ें: %s','(no title)'=>'(शीर्षक रहित)','Open in Studio: %s'=>'स्टूडियो में खोलें: %s','Undo'=>'पूर्ववत करें','Redo'=>'पुनः करें','Show or hide layers'=>'परतें दिखाएँ या छुपाएँ','Show or hide the block library'=>'ब्लॉक लाइब्रेरी दिखाएं या छिपाएं','Show revisions'=>'संशोधन दिखाएँ','Open the normal editor'=>'सामान्य संपादक खोलें','Keyboard shortcuts'=>'कीबोर्ड शॉर्टकट','Preview: desktop'=>'पूर्वावलोकन: डेस्कटॉप','Preview: tablet'=>'पूर्वावलोकन: टैबलेट','Preview: mobile'=>'पूर्वावलोकन: मोबाइल','Copy style of the selected block'=>'चयनित ब्लॉक की शैली कॉपी करें','Paste style onto the selected block'=>'चयनित ब्लॉक पर स्टाइल पेस्ट करें','Copy the selected section'=>'चयनित अनुभाग को कॉपी करें','Paste a copied section'=>'कॉपी किया गया अनुभाग पेस्ट करें','Turn off safe mode'=>'सेफ़ मोड बंद करें','Turn on safe mode (other plugins off, for you, in Studio only)'=>'सेफ़ मोड चालू करें (अन्य प्लगइन बंद, आपके लिए, केवल स्टूडियो में)','Published'=>'प्रकाशित','Scheduled'=>'निर्धारित','Pending review'=>'समीक्षा प्रतीक्षित है','Private'=>'प्राइवेट','Draft'=>'ड्राफ़्ट','All changes saved'=>'सभी परिवर्तन सहेजे गए','Saving…'=>'सेव किया जा रहा है...','Autosaving…'=>'स्वचालित सहेज रहा है…','Unsaved changes'=>'बिना सहेजे गए परिवर्तन','autosaved'=>'स्वतः सहेजा गया','Desktop preview'=>'डेस्कटॉप पूर्वावलोकन','Tablet preview'=>'टैबलेट पूर्वावलोकन','Mobile preview'=>'मोबाइल पूर्वावलोकन','Studio toolbar'=>'स्टूडियो टूलबार','Back to the normal editor'=>'सामान्य संपादक पर वापस जाएं','Page title'=>'पेज शीर्षक','Preview width'=>'पूर्वावलोकन चौड़ाई','Command palette'=>'कमांड पैलेट','View page (opens in a new tab)'=>'पेज देखें (नए टैब में खुलता है)','Update'=>'अपडेट करें','Save draft'=>'ड्राफ्ट सहेजें','Publish'=>'प्रकाशित करें','Restore unsaved changes?'=>'सहेजे गए परिवर्तनों को पुनर्स्थापित करें?','This page has changes that were never saved. They were kept in this browser:'=>'इस पृष्ठ पर ऐसे परिवर्तन हैं जिन्हें कभी सहेजा नहीं गया था। उन्हें इस ब्राउज़र में रखा गया था:','This page has a newer autosave than the saved version:'=>'इस पेज पर सहेजे गए संस्करण की तुलना में एक नया ऑटोसेव उपलब्ध है:','Restore unsaved changes'=>'असंरक्षित परिवर्तन पुनर्स्थापित करें','Discard'=>'रद्द करें','Revisions could not be loaded.'=>'संशोधन लोड नहीं किए जा सके।','Revision restored. Save to keep it, or undo to go back.'=>'संशोधन पुनर्स्थापित किया गया। इसे बनाए रखने के लिए सहेजें, या वापस जाने के लिए पूर्ववत करें।','Close revisions'=>'संशोधन बंद करें','No revisions yet. Each save makes one.'=>'अभी तक कोई संशोधन नहीं हुआ है। हर एक सेव से एक संशोधन बनता है।','Revision from %s'=>'%s से संशोधन','Restore this revision'=>'इस संशोधन को पुनर्स्थापित करें','Cancel'=>'रद्द करें','Safe mode could not be changed.'=>'सेफ मोड बदला नहीं जा सका।','Safe mode is on.'=>'सेफ़ मोड चालू है।','%d other plugin is switched off, for you and in Sandwich Studio only. The live site and other users are not affected.'=>'%d अन्य प्लगइन बंद है, आपके लिए और केवल सैंडविच स्टूडियो में। लाइव साइट और अन्य उपयोगकर्ता प्रभावित नहीं होते हैं।' . "\0" . '%d अन्य प्लगइन्स बंद कर दिए गए हैं, आपके लिए और केवल सैंडविच स्टूडियो में। लाइव साइट और अन्य उपयोगकर्ता प्रभावित नहीं हैं।','Safe mode: switch other plugins off in Studio, for you only'=>'सेफ़ मोड: स्टूडियो में अन्य प्लगइन्स बंद करें, केवल आपके लिए','Safe mode'=>'सुरक्षित मोड','Save your changes.'=>'अपने बदलाव सहेजें।','Undo your last change.'=>'अपने अंतिम परिवर्तन को पूर्ववत् करें।','Redo your last undo.'=>'अपनी अंतिम अनडू क्रिया को फिर से करें।','Show or hide the layers panel.'=>'लेयर्स पैनल को दिखाएँ या छिपाएँ।','Display these keyboard shortcuts.'=>'ये कीबोर्ड शॉर्टकट प्रदर्शित करें।','Select a block first.'=>'पहले एक ब्लॉक चुनें।','Style copied. Paste it onto any block, on this site or another.'=>'शैली कॉपी कर ली गई है। इसे इस साइट या किसी अन्य साइट पर किसी भी ब्लॉक पर पेस्ट करें।','The browser refused to copy.'=>'ब्राउज़र ने कॉपी करने से मना कर दिया।','Section copied. Paste it into any page, on this site or another.'=>'सेक्शन कॉपी कर लिया गया है। इसे इस साइट या किसी अन्य साइट पर किसी भी पेज में पेस्ट करें।','The clipboard does not hold a style copied from Sandwich Studio.'=>'क्लिपबोर्ड में Sandwich Studio से कॉपी की गई कोई शैली मौजूद नहीं है।','Style pasted onto %d block.'=>'%d ब्लॉक पर स्टाइल पेस्ट की गई।' . "\0" . '%d ब्लॉक पर स्टाइल पेस्ट की गई।','That style does not fit the selected block.'=>'वह शैली चयनित ब्लॉक पर लागू नहीं होती है।','The clipboard does not hold a copied section.'=>'क्लिपबोर्ड में कोई कॉपी किया गया अनुभाग नहीं है।','Section pasted.'=>'खंड पेस्ट कर दिया गया है।','Paste style'=>'शैविल पेस्ट करें','Paste section'=>'सेक्शन पेस्ट करें','Press Ctrl+V (or Cmd+V on a Mac) here to paste'=>'यहाँ पेस्ट करने के लिए Ctrl+V (Mac पर Cmd+V) दबाएँ','Copy style'=>'शैली कॉपी करें','Copy section'=>'खंड कॉपी करें','Edit in Sandwich Studio'=>'सैंडविच स्टूडियो में संपादित करें','Saving failed. Check your connection and try again; your changes are kept in this browser.'=>'सहेजने में विफल। अपना कनेक्शन जांचें और पुनः प्रयास करें; आपके परिवर्तन इस ब्राउज़र में सुरक्षित रखे गए हैं।','Published.'=>'प्रकाशित','Saved.'=>'सहेजा गया।','block titleButton link'=>'बटन लिंक','block descriptionA link styled as a button.'=>'बटन के रूप में स्टाइल किया गया एक लिंक।','block keywordbutton'=>'बटन','block keywordlink'=>'लिंक','block keywordcall to action'=>'कार्रवाई के लिए कॉल','block titleColumn'=>'कॉलम','block descriptionA column inside a row. It can hold any block.'=>'एक पंक्ति के अंदर एक स्तंभ। यह किसी भी ब्लॉक को रख सकता है।','block keywordcolumn'=>'स्तंभ','block keywordlayout'=>'लेआउट','block titleLanguage switcher (sample)'=>'भाषा स्विचर (नमूना)','block descriptionLists the site\'s languages from the translation plugin, when one is active. It renders nothing otherwise.'=>'जब कोई अनुवाद प्लगइन सक्रिय होता है, तो यह उससे साइट की भाषाओं की सूची बनाता है। अन्यथा यह कुछ भी प्रदर्शित नहीं करता है।','block keywordlanguage'=>'भाषा','block keywordswitcher'=>'स्विच करने वाला','block titleSample content'=>'नमूना सामग्री','block descriptionA heading and a paragraph, rendered with neutral class names. It is the reference block for the translation contract.'=>'एक शीर्षक और एक पैराग्राफ, जिन्हें तटस्थ क्लास नामों के साथ रेंडर किया गया है। यह अनुवाद अनुबंध के लिए संदर्भ ब्लॉक है।','block keywordsample'=>'सैंपल','block keywordtext'=>'पाठ','block titleIcon'=>'आइकन','block descriptionAn SVG icon. The markup is cleaned before it is shown.'=>'एक SVG आइकन। इसे दिखाने से पहले मार्कअप को साफ किया जाता है।','block keywordicon'=>'आइकन','block keywordsvg'=>'svg','block titleRow'=>'पंक्ति','block descriptionA row of columns. Stays readable if the plugin is ever turned off.'=>'कॉलम की एक पंक्ति। यदि प्लगइन कभी बंद भी कर दिया जाए, तब भी यह पठनीय रहता है।','block keywordrow'=>'पंक्ति','block keywordcolumns'=>'स्तंभ','block titleShortcode (add-on)'=>'शॉर्टकट (ऐड-ऑन)','block descriptionA shortcode from an add-on written for the classic Page Builder Sandwich editor, with the settings the add-on declared.'=>'क्लासिक Page Builder Sandwich एडिटर के लिए लिखे गए एक ऐड-ऑन का शॉर्टकोड, उन सेटिंग्स के साथ जो ऐड-ऑन ने घोषित की थीं।','block keywordshortcode'=>'शॉर्टकट','block keywordadd-on'=>'ऐड-ऑन','block titleWidget area'=>'विजेट क्षेत्र','block descriptionShows the widgets in one of the theme\'s widget areas.'=>'थीम के विजेट क्षेत्रों में से एक में विजेट दिखाता है।','block keywordsidebar'=>'साइडबार','block keywordwidget area'=>'विजेट क्षेत्र','block titleWidget'=>'विजेट','block descriptionShows one of the site\'s registered classic widgets.'=>'साइट के पंजीकृत क्लासिक विजेट्स में से एक को दिखाता है।','block keywordwidget'=>'विजेट']];